var result=[];doc.pages.filter(function(p){return /^Proto macOS (Light|Dark)$/.test(p.name);}).forEach(function(p){var app=p.name.indexOf('Dark')>=0?'Dark/Clean':'Light/Clean';p.layers.filter(function(s){return /^Screen\/macos\/(Light|Dark)\/Clean\/settings/.test(s.name);}).forEach(function(s){var n=0;function walk(l){if(l.name==='settings-detail'){l.layers.forEach(function(sec){if(/^section:/.test(sec.name)){sec.layers.forEach(function(t){if(t.type==='Text'&&t.style.fontSize===12){t.frame.x=12;t.frame.width=800;}});}});}if(l.stackLayout&&l.frame.height===24&&l.style.borders.length){l.style.shadows=[{color:'#0000001a',blur:1,x:0,y:1,spread:0}];n++;}if(l.name==='segmented-control'){l.layers.forEach(function(b){if(b.style.fills.length)b.style.shadows=[{color:'#00000026',blur:2,x:0,y:1,spread:0}];});}if(l.frame.width===26&&l.frame.height===15){l.style.innerShadows=[{color:'#0000001a',blur:1,x:0,y:0.5,spread:0}];} (l.layers||[]).forEach(walk);}walk(s);result.push({id:s.id,polished:n});});});console.log(JSON.stringify(result));